import { isUndefined } from '@nestjs/common/internal';
/**
 * @publicApi
 */
export class IncomingRequestDeserializer {
    deserialize(value, options) {
        return this.isExternal(value) ? this.mapToSchema(value, options) : value;
    }
    isExternal(value) {
        if (!value) {
            return true;
        }
        if (!isUndefined(value.pattern) ||
            !isUndefined(value.data)) {
            return false;
        }
        return true;
    }
    mapToSchema(value, options) {
        if (!options) {
            return {
                pattern: undefined,
                data: undefined,
            };
        }
        return {
            pattern: options.channel,
            data: value,
        };
    }
}
